  package popcount

  // Popcount returns the number of set bits across all words of xs.
  // It uses an inline SWAR popcount per word, avoiding calls to
  // bits.OnesCount64 and the length-check cascade.
  func Popcount(xs []uint64) int {
  	n := 0
  	for _, x := range xs {
  		x -= (x >> 1) & 0x5555555555555555
  		x = (x & 0x3333333333333333) + ((x >> 2) & 0x3333333333333333)
  		x = (x + (x >> 4)) & 0x0f0f0f0f0f0f0f0f
  		n += int((x * 0x0101010101010101) >> 56)
  	}
  	return n
  }
